/**
 * @brief The two intractors: variable-speed fans drawing air from under the
 *        floor, driven by whichever of three demands wants the most.
 *
 * `intractors`, dispatched SLOW. Everything here is declared in
 * tables/programs.toml; the body is hand-written beside this file. A name
 * without a leading underscore is a row or a block the POU is connected to;
 * one with is its own.
 */
class IntractorController final : public Plc::Program {

public:

    /** @name VAR_INPUT
     *  @{ */

    Vars::RefIn<float> cool_dem;
    Vars::RefIn<float> rot_vent;
    Vars::RefIn<float> humid_dem;
    Vars::RefIn<float> ground_speed;
    Vars::RefIn<float> start_dem;
    Vars::RefIn<float> full_dem;
    Vars::RefIn<bool>  cool_ok;
    Vars::RefIn<bool>  ground_ok;
    Vars::RefIn<bool>  dry_ok;

    /** @} */

    /** @name VAR_OUTPUT
     *  @{ */

    Vars::RefOut<float> intr[2];

    /** @} */

private:

    /** @name Sizes
     *  How many rows or instances each array member has, from the
     *  table. What a body loops over, so a site constant cannot get
     *  out of step with what is declared.
     *  @{ */

    static const uint8_t N_INTR = 2;

    /** @} */

    /** @brief Every readable row this program connects to, as bare
     *  indices: what the base sweeps for validity before each
     *  activation. Parameters are not here - an operator's number is
     *  always valid, and checking one would cost a walk to learn nothing. */
    Vars::VarRef _watched[6];

public:
    /** @brief The instance name and rate class programs.toml
     *  declares, so neither can drift from the configuration. */
    IntractorController(const SetupContext& ctx, Vars::Bank& io)
        : Program(ctx, "intractors", Tasks::GROUP_SLOW, io) {}

protected:
    /** @brief Resolve every name. Runs inside the program's writer
     *  window, so an output is CLAIMED here. */
    void bind(Vars::Bank& io) override;

    /** @brief One activation of the law. */
    void run(ProgramContext& c) override;

private:

    /** @brief Where these go when this law is not acting, off the row's own
     *  declared safe value. NOT stopped: some air is always wanted. */
    float _safe_speed() const;
};

inline void IntractorController::bind(Vars::Bank& io) {
    cool_dem     = io.resolve_in<float>("cli_coolDem");
    rot_vent     = io.resolve_in<float>("cli_rotVentDem");
    humid_dem    = io.resolve_in<float>("cli_humidDem");
    ground_speed = io.resolve_in<float>("cli_groundSpeed");
    start_dem    = io.resolve_in<float>("cli_intakeStartDem");
    full_dem     = io.resolve_in<float>("cli_intakeFullDem");
    cool_ok      = io.resolve_in<bool>("cli_intakeCoolOk");
    ground_ok    = io.resolve_in<bool>("cli_groundHeatOk");
    dry_ok       = io.resolve_in<bool>("cli_intakeDryOk");
    intr[0]      = io.resolve_out<float>("cli_intr1");
    intr[1]      = io.resolve_out<float>("cli_intr2");

    // The readings this law is entitled to expect. The base walks them
    // before each activation, so an input that has stopped being believable
    // is DEGRADED whether or not the law thought to ask.
    _watched[0] = cool_dem.r;
    _watched[1] = rot_vent.r;
    _watched[2] = humid_dem.r;
    _watched[3] = cool_ok.r;
    _watched[4] = ground_ok.r;
    _watched[5] = dry_ok.r;
    set_inputs(_watched, 6);
    set_health_row(io.resolve_out<uint8_t>("prog_intractors"));
}

